final class OrderTotal {
    int calculate(int subtotalCents, boolean premium, String country) {
        if (subtotalCents < 0) {
            throw new IllegalArgumentException("negative subtotal");
        }
        int discounted = premium ? applyPremiumDiscount(subtotalCents) : subtotalCents;
        return applyRegionalTax(discounted, country);
    }

    private int applyPremiumDiscount(int amount) {
        return amount - amount * 10 / 100;
    }

    private int applyRegionalTax(int amount, String country) {
        int rate = "SK".equals(country) ? 20 : 10;
        return amount + amount * rate / 100;
    }
}

